using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEngine;
namespace AboutMe.Editor
{
    public static class PartyMachineryTests
    {
        static readonly FieldInfo Cache=typeof(CampusGeometry).GetField("solids",BindingFlags.NonPublic|BindingFlags.Static);
        public static CampusSolid[] Flat=>PartyLootTests.Flat;
        public static Vector3 Button(EffectState e)=>e.position-Quaternion.Euler(0,90,0)*e.velocity*2.35f;
        public static void Place(Match m,Player p,Vector3 at){p.position=at;p.motorHeight=at.y;p.impulse=Vector3.zero;p.airborne=false;p.verticalSpeed=0;if(m.BodyWorld!=null)m.BodyWorld.Reset(p);}
        public static float Top(Match m,EffectState e,float x=0){var box=Match.MachineShapes(e).First();box.Surface(e.position+Vector3.right*x,1,out var top);return top;}
        static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
        [MenuItem("About Me/Tests/Party machinery authority")]
        public static void Run()
        {
            var old=Cache.GetValue(null);var failures=new List<string>();int passed=0;
            void Test(string name,Action run){Cache.SetValue(null,Flat);try{run();passed++;Debug.Log("PARTY_MACHINE_PASS "+name);}catch(Exception ex){failures.Add(name+": "+ex.Message);Debug.LogError("PARTY_MACHINE_FAIL "+name+": "+ex);}}
            try
            {
                Test("pressure fan is live only while a player stands on plate",()=>{using(var m=PartyFieldTests.Make("step-switch")){var e=PartyFieldTests.Deploy(m);var p=m.Players["p1"];Place(m,p,Button(e)+Vector3.up*.85f);var item=PartyFieldTests.Ground(m,e.position+Vector3.forward*2+Vector3.up*.2f);float z=item.position.z;PartyFieldTests.Tick(m,.3f);Check(e.machine.powered&&item.position.z>z+.1f,"plate failed to link fan");Place(m,p,new Vector3(10,1,0));PartyFieldTests.Tick(m,.04f);Check(!e.machine.powered,"fan latched after leaving plate");}});
                Test("weight plate rejects player and Persona, accepts only loose box",()=>{using(var m=PartyFieldTests.Make("weight-switch")){var e=PartyFieldTests.Deploy(m);Place(m,m.Players["p1"],Button(e)+Vector3.up*.85f);var item=PartyFieldTests.Ground(m,Button(e)+Vector3.up*.2f);PartyFieldTests.Tick(m,.04f);Check(!e.machine.powered,"player or life powered weight plate");var prop=new PublicProp{id="crate",visual="box",position=Button(e)+Vector3.up*.45f};m.Props.Add(prop);PartyFieldTests.Tick(m,.04f);Check(e.machine.powered,"public box did not open door");prop.holder="p2";m.Players["p2"].publicProp=prop.id;PartyFieldTests.Tick(m,.04f);Check(!e.machine.powered&&item.ownerId=="p2"&&item.state==ItemState.Ground,"lifting did not cut signal or stole life");}});
                Test("closed door blocks, public button opens, occupied door defers close",()=>{using(var m=PartyFieldTests.Make("timed-door")){var e=PartyFieldTests.Deploy(m);var b=m.Players["p1"];Place(m,b,e.position+Vector3.up*.85f+Vector3.back*.8f);float z=b.position.z;PartyFieldTests.Tick(m,.2f,"p1",0,1);Check(b.position.z<e.position.z-.45f,"closed door did not block");Place(m,b,Button(e)+Vector3.up*.85f);PartyFieldTests.Input(m,"p1","interact");Check(e.machine.powered,"public E failed");Place(m,b,e.position+Vector3.up*.85f);PartyFieldTests.Tick(m,1.1f);Check(e.machine.powered&&e.machine.mode=="waiting_clear"&&b.stability==100,"door closed inside body");Place(m,b,new Vector3(10,1,0));PartyFieldTests.Tick(m,.04f);Check(!e.machine.powered,"door did not close when clear");}});
                Test("closed door blocks grabs, recovery and actual thrown lives",()=>{using(var m=PartyFieldTests.Make("timed-door")){var e=PartyFieldTests.Deploy(m);var a=m.Players["p0"];var b=m.Players["p1"];Place(m,a,e.position+Vector3.up*.85f+Vector3.back*.65f);Place(m,b,e.position+Vector3.up*.85f+Vector3.forward*.65f);PartyFieldTests.Tick(m,.5f);PartyFieldTests.Input(m,"p0","grab");PartyFieldTests.Tick(m,.18f);Check(a.grabbing=="","grab crossed closed door");var item=PartyFieldTests.Ground(m,e.position+Vector3.up*.2f+Vector3.forward*.8f);PartyFieldTests.Input(m,"p0","interact");Check(item.state==ItemState.Ground,"E crossed closed door");item.state=ItemState.Thrown;item.thrownBy="p0";item.position=a.position+Vector3.up*.2f;item.velocity=Vector3.forward*14;PartyFieldTests.Tick(m,.12f);Check(item.state==ItemState.Ground&&item.position.z<e.position.z&&b.stability==100,"real life projectile crossed door");}});
                Test("closed device remains dismantlable from outside",()=>{using(var m=PartyFieldTests.Make("timed-door")){var e=PartyFieldTests.Deploy(m);m.Item(m.Players["p1"].equipped).asset.templateId="Melee";m.Item(m.Players["p1"].equipped).asset.visualId="ukulele-cc0";Place(m,m.Players["p1"],e.position+Vector3.up*.85f+Vector3.back*1.2f);PartyFieldTests.Input(m,"p1","use_item");PartyFieldTests.Tick(m,.4f);Check(e.health==1,"door blocked its own dismantle hit");PartyFieldTests.Tick(m,1.3f);PartyFieldTests.Input(m,"p1","use_item");PartyFieldTests.Tick(m,.4f);Check(!m.Effects.Contains(e),"two hits did not dismantle door");}});
                Test("ground asset obstructs closing without consuming or relocating it",()=>{using(var m=PartyFieldTests.Make("timed-door")){var e=PartyFieldTests.Deploy(m);Place(m,m.Players["p1"],Button(e)+Vector3.up*.85f);PartyFieldTests.Input(m,"p1","interact");var item=PartyFieldTests.Ground(m,e.position+Vector3.up*.2f);PartyFieldTests.Tick(m,1.1f);Check(e.machine.powered&&item.state==ItemState.Ground&&item.ownerId=="p2","door crushed/moved ground life");}});
                Test("turntable publicly operated rotates real Ground item, Q stops immediately",()=>{using(var m=PartyFieldTests.Make("turntable-wheel")){var e=PartyFieldTests.Deploy(m);var p=m.Players["p1"];Place(m,p,Button(e)+Vector3.up*.85f);var item=PartyFieldTests.Ground(m,e.position+Vector3.right+Vector3.up*(Top(m,e)+.35f-e.position.y));PartyFieldTests.Input(m,"p1","interact");PartyFieldTests.Tick(m,.5f);Check(e.machine.angle>20&&Mathf.Abs(item.position.z-e.position.z)>.2f&&item.ownerId=="p2","wheel did not move item");PartyFieldTests.Input(m,"p1","cancel");float a=e.machine.angle;PartyFieldTests.Tick(m,.1f);Check(Mathf.Abs(e.machine.angle-a)<.01f&&e.machine.operatorId=="","Q did not brake");}});
                Test("walking away and disconnect stop crank, E prioritizes real recovery",()=>{foreach(bool disconnect in new[]{false,true})using(var m=PartyFieldTests.Make("turntable-wheel")){var e=PartyFieldTests.Deploy(m);var p=m.Players["p1"];Place(m,p,Button(e)+Vector3.up*.85f);PartyFieldTests.Input(m,"p1","interact");if(disconnect)m.Disconnect("p1");else PartyFieldTests.Tick(m,.02f,"p1",1,0);PartyFieldTests.Tick(m,.04f);Check(e.machine.operatorId=="","crank did not stop");}using(var m=PartyFieldTests.Make("turntable-wheel")){var e=PartyFieldTests.Deploy(m);Place(m,m.Players["p1"],Button(e)+Vector3.up*.85f);var item=PartyFieldTests.Ground(m,Button(e)+Vector3.up*.2f);PartyFieldTests.Input(m,"p1","interact");Check(item.state==ItemState.Carried&&e.machine.operatorId=="","crank stole recovery input");}});
                Test("sweep warns, ground hit occurs once, airborne victim untouched",()=>{using(var m=PartyFieldTests.Make("rotating-sweep")){var e=PartyFieldTests.Deploy(m);var p=m.Players["p1"];Place(m,p,e.position+Vector3.right+Vector3.up*.85f);PartyFieldTests.Tick(m,.3f);Check(p.stability==100&&e.machine.mode=="warning","sweep skipped warning");PartyFieldTests.Tick(m,.8f);Check(m.CombatEvents.Count(x=>x.kind=="party_sweep"&&x.targetId=="p1")==1,"sweep missed or repeated hit");}using(var m=PartyFieldTests.Make("rotating-sweep")){var e=PartyFieldTests.Deploy(m);var p=m.Players["p1"];PartyFieldTests.Tick(m,.65f);Place(m,p,e.position+Vector3.right+Vector3.up*3);p.airborne=true;p.verticalSpeed=3;PartyFieldTests.Tick(m,.12f);Check(p.stability==100,"sweep hit jumping player");}});
                Test("opposite weights reverse plank tilt, Persona adds no load",()=>{using(var m=PartyFieldTests.Make("balance-plank")){var e=PartyFieldTests.Deploy(m);var p=m.Players["p1"];Place(m,p,new Vector3(e.position.x+1,Top(m,e,1)+1,e.position.z));PartyFieldTests.Tick(m,.22f);Check(e.machine.angle< -3&&Mathf.Abs(e.machine.angle)<=12,"weight did not tilt");Place(m,p,new Vector3(10,1,0));var prop=new PublicProp{id="crate",visual="box",position=new Vector3(e.position.x-1.4f,Top(m,e,-1.4f)+.6f,e.position.z)};m.Props.Add(prop);PartyFieldTests.Tick(m,.4f);Check(e.machine.angle>0,"counterweight did not reverse");}});
                Test("elevator carries player and original life to bounded height then returns",()=>{using(var m=PartyFieldTests.Make("floor-elevator")){var e=PartyFieldTests.Deploy(m);var b=m.Players["p1"];Place(m,b,Button(e)+Vector3.up*.85f);PartyFieldTests.Input(m,"p1","interact");Place(m,b,new Vector3(e.position.x,Top(m,e)+1,e.position.z));var item=PartyFieldTests.Ground(m,new Vector3(e.position.x+.7f,Top(m,e)+.35f,e.position.z));PartyFieldTests.Tick(m,2.05f);Check(e.machine.height==1.2f&&b.position.y>2.25f&&item.position.y>1.6f&&item.state==ItemState.Ground,"elevator did not carry original objects "+b.position+" item="+item.position);PartyFieldTests.Tick(m,3f);Check(e.machine.height==0&&e.machine.used&&b.position.y<1.35f&&item.ownerId=="p2","elevator did not return once");}});
                Test("get-up floor follows moving deck",()=>{using(var m=PartyFieldTests.Make("floor-elevator")){var e=PartyFieldTests.Deploy(m);e.machine.height=1;var b=m.Players["p1"];b.position=new Vector3(e.position.x,Top(m,e)+.4f,e.position.z);b.bodyMode=BodyMode.Grounded;Check(m.TryBodyGetUp(b,Vector3.up)&&b.getUpPosition.y>2.1f,"get-up targeted campus below moving deck");}});
                Test("seesaw requires opposite grounded person and heavier load",()=>{using(var m=PartyFieldTests.Make("seesaw-flip")){var e=PartyFieldTests.Deploy(m);var b=m.Players["p1"];Place(m,b,new Vector3(e.position.x-1,Top(m,e,-1)+1,e.position.z));PartyFieldTests.Tick(m,.1f);Check(!m.CombatEvents.Any(x=>x.kind=="party_seesaw_launch"),"single rider launched alone");m.Props.Add(new PublicProp{id="crate",visual="box",position=new Vector3(e.position.x+1.6f,Top(m,e,1.6f)+.6f,e.position.z)});PartyFieldTests.Tick(m,.16f);Check(b.airborne&&m.CombatEvents.Count(x=>x.kind=="party_seesaw_launch")==1,"opposite weight did not launch");}});
                Test("rotary gate turns by walking input and brakes on release",()=>{using(var m=PartyFieldTests.Make("rotary-gate")){var e=PartyFieldTests.Deploy(m);var b=m.Players["p1"];Place(m,b,e.position+Vector3.right+Vector3.up*.85f);PartyFieldTests.Tick(m,.2f,"p1",0,-1);Check(Mathf.Abs(e.machine.angle)>5,"walk did not push arm angle="+e.machine.angle+" powered="+e.machine.powered+" pos="+b.position);float a=e.machine.angle;PartyFieldTests.Tick(m,.1f);Check(!e.machine.powered&&Mathf.Abs(e.machine.angle-a)<.01f,"gate kept motor running without input");}});
                Test("cart one-shot touches public elevator button then stops",()=>{using(var m=PartyFieldTests.Make("wind-up-cart")){var e=PartyFieldTests.Deploy(m);var prop=m.Props.First();var source=m.Item(m.Players["p1"].equipped);var target=new EffectState{id="lift",kind="PartyMechanic",mechanicId="floor-elevator",owner="p1",sourceInstance=source.id,velocity=Vector3.forward,position=prop.position+Vector3.forward*2+Vector3.right*2.35f-Vector3.up*.45f,deadline=m.Time+7,machine=new MachineState(),health=2};m.Effects.Add(target);PartyFieldTests.Tick(m,.5f);PartyFieldTests.Input(m,"p0","use_item");PartyFieldTests.Tick(m,1.2f);Check(target.machine.used&&e.machine.mode=="spent"&&prop.thrower==""&&m.CombatEvents.Count(x=>x.kind=="party_cart_button")==1,"cart failed single signal mode="+e.machine.mode+" pos="+prop.position+" button="+Button(target)+" used="+target.machine.used+" events="+string.Join(",",m.CombatEvents.Select(x=>x.kind)));}});
                Test("public G and held F re-aim cart without Persona transfer",()=>{using(var m=PartyFieldTests.Make("wind-up-cart")){var e=PartyFieldTests.Deploy(m);var prop=m.Props.First();var a=m.Players["p0"];PartyFieldTests.Tick(m,.5f);Place(m,a,prop.position+Vector3.back*.9f+Vector3.up*.4f);PartyFieldTests.Input(m,"p0","grab");PartyFieldTests.Tick(m,.3f);Check(prop.holder=="p0","G could not hold button car");a.yaw=90;PartyFieldTests.Tick(m,.1f);var origin=prop.position;PartyFieldTests.Input(m,"p0","use_item");PartyFieldTests.Tick(m,.3f);Check(prop.holder==""&&a.publicProp==""&&e.machine.mode=="driving"&&e.velocity.x>.9f,"held F did not turn and release car");PartyFieldTests.Tick(m,.3f);Check(prop.position.x>origin.x+.5f&&m.Remaining("p0")==4,"car did not move new heading or changed life");}});
                Test("machine deployment rejects uneven floor wall people and overlapping machine",()=>{foreach(string condition in new[]{"wall","person","machine"})using(var m=PartyFieldTests.Make("balance-plank")){if(condition=="wall")Cache.SetValue(null,Flat.Concat(new[]{new CampusSolid{name="wall",center=new Vector3(1.7f,1.2f,3.7f),size=new Vector3(.3f,2.4f,3)}}).ToArray());if(condition=="person")Place(m,m.Players["p1"],new Vector3(0,1,3.7f));if(condition=="machine")m.Effects.Add(new EffectState{id="old",kind="PartyMechanic",mechanicId="balance-plank",owner="p1",sourceInstance=m.Players["p1"].equipped,position=new Vector3(0,.15f,5),velocity=Vector3.forward,deadline=m.Time+4,machine=new MachineState()});PartyFieldTests.Input(m,"p0","use_item");PartyFieldTests.Tick(m,.35f);Check(!m.Effects.Any(e=>e.owner=="p0"),"unsafe deployment accepted "+condition);}});
                Test("budget full still permits existing door but rejects ninth machine",()=>{using(var m=PartyFieldTests.Make("timed-door")){var e=PartyFieldTests.Deploy(m);for(int i=0;i<7;i++)m.Effects.Add(new EffectState{id="old"+i,kind="PartyMechanic",mechanicId="fan-volume",owner="p1",sourceInstance=m.Players["p1"].equipped,position=new Vector3(-15,.15f,i),deadline=m.Time+4});PartyFieldTests.Tick(m,.5f);PartyFieldTests.Input(m,"p0","use_item");PartyFieldTests.Tick(m,.34f);Check(e.machine.powered&&m.Effects.Count==8,"budget blocked existing door toggle");}using(var m=PartyFieldTests.Make("balance-plank")){for(int i=0;i<8;i++)m.Effects.Add(new EffectState{id="old"+i,kind="PartyMechanic",mechanicId="fan-volume",owner="p1",sourceInstance=m.Players["p1"].equipped,position=new Vector3(-15,.15f,i),deadline=m.Time+4});PartyFieldTests.Input(m,"p0","use_item");PartyFieldTests.Tick(m,.34f);Check(m.Effects.Count==8,"ninth machinery deployed");}});
                Test("consumed source and finish clean all machinery, original lives conserved",()=>{foreach(var d in PartyMechanicRegistry.All.Where(x=>x.family=="machinery"))using(var m=PartyFieldTests.Make(d.id)){var e=PartyFieldTests.Deploy(m);Check(m.Players.Keys.All(id=>m.Remaining(id)==4),"machine created life");m.Item(e.sourceInstance).state=ItemState.Consumed;PartyFieldTests.Tick(m,.02f);Check(!m.Effects.Contains(e)&&!m.Props.Any(x=>x.id.StartsWith("device-")),"source consume leaked machine");m.Finish("timeout");Check(!m.Effects.Any(x=>x.kind=="PartyMechanic"),"finish leaked machinery");}});
            }
            finally{Cache.SetValue(null,old);}if(failures.Count>0)throw new Exception(string.Join("\n",failures));Debug.Log("PARTY_MACHINERY_PASSED "+passed+" authority scenarios / ten machinery interactions");
        }
    }
}
